#!/usr/bin/env python3
"""Build a self-contained paper-asset selection page from the comparison data."""

from __future__ import annotations

import json
from pathlib import Path

from build_articraft_lam_comparison_html import build_data


ROOT = Path(__file__).resolve().parents[2]
RENDER_ROOT = ROOT / "failure_case_renders"
OUTPUT = RENDER_ROOT / "articraft_lam_category_selection.html"


TEMPLATE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PV-A / Articraft / LAM 论文资产选择器</title>
<style>
:root{color-scheme:light;--ink:#202421;--muted:#66706a;--line:#d9ddd9;--paper:#f5f6f3;--surface:#fff;--green:#26734d;--green-soft:#e8f3ed;--blue:#315f88;--blue-soft:#e8f1f8;--danger:#a33b32}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif;letter-spacing:0}button,input,select{font:inherit}.top{background:#1f2923;color:#fff;padding:24px max(20px,calc((100vw - 1540px)/2)) 20px}.top h1{font-size:24px;margin:0 0 7px}.top p{color:#cfd8d2;margin:0;max-width:1000px}.summary{display:flex;gap:22px;flex-wrap:wrap;margin-top:16px}.summary strong{display:block;font-size:19px}.summary span{color:#bfcac3;font-size:12px}.toolbar{position:sticky;top:0;z-index:10;background:#fffffff5;border-bottom:1px solid var(--line);box-shadow:0 2px 8px #1f292312}.controls{max-width:1540px;margin:auto;padding:10px 20px;display:grid;grid-template-columns:minmax(260px,1.8fr) repeat(2,minmax(145px,.7fr)) auto auto;gap:9px;align-items:end}.control label{display:block;color:var(--muted);font-size:11px;margin-bottom:3px}.control input[type=search],.control select{width:100%;height:36px;border:1px solid #bbc2bc;border-radius:5px;padding:0 10px;background:#fff}.check{height:36px;display:flex;align-items:center;gap:7px;white-space:nowrap}.actions{display:flex;gap:6px;flex-wrap:wrap}.button{height:36px;border:1px solid #bbc2bc;border-radius:5px;background:#fff;color:var(--ink);padding:0 10px;cursor:pointer}.button:hover{border-color:#788079;background:#f7f8f6}.status{max-width:1540px;margin:14px auto 8px;padding:0 20px;color:var(--muted)}main{max-width:1540px;margin:auto;padding:0 20px 55px}.group{background:var(--surface);border:1px solid var(--line);border-radius:7px;margin:10px 0;overflow:hidden}.group-head{padding:12px 15px;display:flex;gap:12px;align-items:center;border-bottom:1px solid var(--line)}.group-head h2{font-size:15px;margin:0;flex:1;overflow-wrap:anywhere}.group-head small{color:var(--muted)}.group-body{padding:0 15px 18px}.source{padding-top:15px}.source+.source{margin-top:18px;border-top:1px dashed #cfd4cf}.source-head{display:flex;gap:10px;align-items:baseline;margin-bottom:10px}.source-head h3{font-size:14px;margin:0}.source-head span{color:var(--muted);font-size:12px}.asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px}.pva-grid{grid-template-columns:repeat(auto-fill,minmax(230px,1fr))}.asset{border:1px solid var(--line);border-radius:6px;overflow:hidden;background:#fafbf9}.asset.selected{border-color:var(--green);box-shadow:0 0 0 2px #26734d33}.asset-meta{padding:8px 9px;border-bottom:1px solid var(--line);min-height:58px}.asset-title{font-size:12px;font-weight:650;line-height:1.3;overflow-wrap:anywhere}.asset-sub{display:flex;gap:8px;flex-wrap:wrap;margin-top:4px;color:var(--muted);font-size:11px}.pva-mark{color:var(--green);font-weight:650}.rating,.broken{color:var(--danger);font-weight:650}.frozen{color:var(--green);font-weight:650}.fallback{color:#9a5b00;font-weight:650}.pick{display:flex;align-items:center;gap:6px;padding:7px 9px;color:var(--muted);font-size:11px;cursor:pointer}.pair{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.shot{position:relative;aspect-ratio:1;background:#eef0ed;border:0;padding:0;cursor:zoom-in;overflow:hidden}.shot img{width:100%;height:100%;display:block;object-fit:contain}.shot span{position:absolute;left:5px;bottom:5px;padding:2px 6px;background:#182019cf;color:#fff;border-radius:3px;font-size:10px}.placeholder{width:100%;height:100%;display:grid;place-items:center;color:#89908b;font-size:11px}.empty{padding:60px 20px;text-align:center;color:var(--muted);background:#fff;border:1px solid var(--line)}dialog{border:0;padding:0;background:#161a17;color:#fff;width:100vw;height:100vh}.lightbox{height:100%;display:grid;grid-template-rows:auto 1fr}.lightbox-head{display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:#202622}.close{width:38px;height:34px;border:1px solid #657069;border-radius:5px;background:transparent;color:#fff;font-size:21px;cursor:pointer}.lightbox-stage{min-height:0;display:grid;place-items:center;padding:12px}.lightbox-stage img{max-width:100%;max-height:100%;object-fit:contain}@media(max-width:900px){.controls{grid-template-columns:1fr 1fr}.search{grid-column:1/-1}.actions{grid-column:1/-1}.asset-grid,.pva-grid{grid-template-columns:1fr}}@media(max-width:520px){.controls{grid-template-columns:1fr}.search,.actions{grid-column:auto}}
</style></head><body>
<header class="top"><h1>PV-A / Articraft / LAM 论文资产选择器</h1><p>选择要进入论文的类别，并为每类分别挑选 1 个 PV-A 高质量资产、1 个 Articraft 资产和 1 个 LAM 资产。</p><div class="summary" id="summary"></div></header>
<div class="toolbar"><div class="controls"><div class="control search"><label for="search">搜索类别或资产 ID</label><input id="search" type="search" placeholder="例如 folding_chair"></div><div class="control"><label for="level">匹配级别</label><select id="level"><option value="all">全部</option><option value="exact">完全同名</option><option value="near">同类 / 近同类</option><option value="related">相关家族 / 机构</option></select></div><label class="check"><input id="only-selected" type="checkbox">仅看已选类别</label><div class="actions"><button class="button" id="select-visible" type="button">勾选当前类别</button><button class="button" id="clear-all" type="button">清空类别</button><button class="button" id="export" type="button">导出选择 JSON</button><button class="button" id="download" type="button">下载已选资产索引 ZIP</button><button class="button" id="import" type="button">导入选择 JSON</button><input id="import-file" type="file" accept="application/json" hidden></div></div></div>
<div class="status" id="status"></div><main id="groups"></main>
<footer class="top"><p>选择状态保存在当前浏览器；导出的选择索引不包含渲染 PNG。HTML 已内嵌图片，原始 URDF/网格文件位于配套资产包，并通过索引中的 package_path 定位；PV-A 纹理只保留引用，Articraft 无检测到纹理，LAM 原始材质纹理随资产包保留。</p></footer>
<dialog id="lightbox"><div class="lightbox"><div class="lightbox-head"><span id="lightbox-title"></span><button class="close" id="lightbox-close" type="button">×</button></div><div class="lightbox-stage"><img id="lightbox-image" alt="放大图"></div></div></dialog>
<script id="viewer-data" type="application/json">__VIEWER_DATA__</script><script id="image-data" type="application/json">__IMAGE_DATA__</script><script>
const DATA=JSON.parse(document.getElementById('viewer-data').textContent),IMAGES=JSON.parse(document.getElementById('image-data').textContent),$=id=>document.getElementById(id),KEY='articraft-lam-paper-selection-v1';
const labels={exact:'完全同名',near:'同类 / 近同类',related:'相关家族 / 机构'};let observer;const state={query:'',level:'all',onlySelected:false,selected:new Set(),pva:{},art:{},lam:{}};
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function loadState(){try{const x=JSON.parse(localStorage.getItem(KEY)||'{}');state.selected=new Set(Array.isArray(x.selected)?x.selected:[]);state.pva=x.pva||{};state.art=x.art||{};state.lam=x.lam||{};}catch(_){}}
function saveState(){try{localStorage.setItem(KEY,JSON.stringify({selected:[...state.selected],pva:state.pva,art:state.art,lam:state.lam}));}catch(_){} }
function imageButton(id,label,title){return `<button class="shot" data-image="${id}" data-title="${esc(title+' · '+label)}"><span>${label}</span><div class="placeholder">展开后加载</div></button>`;}
function pair(asset,title){return `<div class="pair">${imageButton(asset.rest,'闭合',title)}${imageButton(asset.midstate,'打开（midstate）',title)}</div>`;}
function choiceCard(group,asset,source,selected){const id=source+'-'+group.category+'-'+(asset.asset_id||asset.seed);const title=asset.asset_id||asset.generator_name+' · '+asset.seed;const meta=source==='pva'?`<span class="pva-mark">${esc(asset.generator_index)} · ${esc(asset.seed)}</span><span>${esc(asset.relation)}</span>`:source==='art'?`<span class="rating">评分 ${asset.rating}</span>`:`<span class="${asset.tier==='broken'?'broken':''}">${esc(asset.tier)}</span><span>元数据 ${asset.metadata_asset_count}</span>${asset.in_frozen_100?'<span class="frozen">Frozen-100</span>':''}${asset.render_mode==='combined_assembly_static_fallback'?'<span class="fallback">静态合并网格</span>':''}`;return `<article class="asset ${selected?'selected':''}"><label class="pick"><input type="radio" name="${esc(source+'-'+group.category)}" data-source="${source}" data-category="${esc(group.category)}" value="${esc(asset.asset_id||asset.seed)}" ${selected?'checked':''}>选择此资产</label><div class="asset-meta"><div class="asset-title">${esc(title)}</div><div class="asset-sub">${meta}</div></div>${pair(asset,title)}</article>`;}
function groupMatches(g){return !state.query||[g.category,...g.pva_assets.map(x=>x.generator_name+' '+x.seed),...g.art_assets.map(x=>x.asset_id),...g.lam_assets.flatMap(x=>[x.category,x.asset_id])].join(' ').toLowerCase().includes(state.query);}
function visibleGroups(){return DATA.groups.filter(g=>(state.level==='all'||g.level===state.level)&&groupMatches(g)&&(!state.onlySelected||state.selected.has(g.category)));}
function render(){const groups=visibleGroups();$('groups').innerHTML=groups.length?groups.map(g=>{const pva=state.pva[g.category]||g.pva_assets[0].seed,art=state.art[g.category]||g.art_assets[0]?.asset_id,lam=state.lam[g.category]||g.lam_assets[0]?.asset_id;return `<section class="group"><div class="group-head"><input type="checkbox" class="include" data-category="${esc(g.category)}" ${state.selected.has(g.category)?'checked':''}><h2>${esc(g.category)}</h2><span class="badge">${esc(labels[g.level])}</span><small>PV-A 3 候选 · Articraft ${g.art_assets.length} · LAM ${g.lam_assets.length}</small></div><div class="group-body"><section class="source"><div class="source-head"><h3>PV-A（高质量候选）</h3><span>选择 1 个</span></div><div class="asset-grid pva-grid">${g.pva_assets.map(a=>choiceCard(g,a,'pva',a.seed===pva)).join('')}</div></section><section class="source"><div class="source-head"><h3>Articraft（低评分）</h3><span>选择 1 个</span></div><div class="asset-grid">${g.art_assets.map(a=>choiceCard(g,a,'art',a.asset_id===art)).join('')}</div></section><section class="source"><div class="source-head"><h3>LAM</h3><span>选择 1 个</span></div><div class="asset-grid">${g.lam_assets.map(a=>choiceCard(g,a,'lam',a.asset_id===lam)).join('')}</div></section></div></section>`;}).join(''):'<div class="empty">没有符合当前筛选条件的类别。</div>';$('status').textContent=`当前显示 ${groups.length} 个类别 · 已选 ${state.selected.size} 个类别 · 每类可选 3 个 PV-A 候选`;document.querySelectorAll('.shot[data-image]').forEach(x=>x.addEventListener('click',()=>openImage(x)));document.querySelectorAll('.include').forEach(x=>x.addEventListener('change',e=>{const c=e.target.dataset.category;e.target.checked?state.selected.add(c):state.selected.delete(c);saveState();updateSummary();}));document.querySelectorAll('input[type=radio]').forEach(x=>x.addEventListener('change',e=>{const c=e.target.dataset.category,s=e.target.dataset.source;state[s][c]=e.target.value;saveState();render();}));hydrate();}
function hydrate(){if(observer)observer.disconnect();observer=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const b=e.target,i=document.createElement('img');i.alt=b.dataset.title;i.loading='lazy';i.src=IMAGES[b.dataset.image];b.querySelector('.placeholder').replaceWith(i);observer.unobserve(b);}),{rootMargin:'300px'});document.querySelectorAll('.shot[data-image]:not(:has(img))').forEach(x=>observer.observe(x));}
function updateSummary(){$('summary').innerHTML=`<div><strong>${DATA.groups.length}</strong><span>匹配类别组</span></div><div><strong>${state.selected.size}</strong><span>已选类别</span></div><div><strong>${DATA.stats.pva_categories}</strong><span>PV-A 类 · 每类 3 个候选</span></div><div><strong>${DATA.stats.art_assets}</strong><span>Articraft 资产</span></div><div><strong>${DATA.stats.lam_unique_assets}</strong><span>LAM 资产</span></div>`;}
function chosenGroups(){return DATA.groups.filter(g=>state.selected.has(g.category)).map(g=>{const p=state.pva[g.category]||g.pva_assets[0].seed,a=state.art[g.category]||g.art_assets[0]?.asset_id,l=state.lam[g.category]||g.lam_assets[0]?.asset_id;return {category:g.category,level:g.level,pva:g.pva_assets.find(x=>x.seed===p),articraft:g.art_assets.find(x=>x.asset_id===a),lam:g.lam_assets.find(x=>x.asset_id===l)};});}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportSelection(){const groups=chosenGroups();const blob=new Blob([JSON.stringify({schema_version:1,generated_at:new Date().toISOString(),groups},null,2)],{type:'application/json'});downloadBlob(blob,'articraft_lam_paper_selection.json');}
function assetIndex(groups){const records=[];for(const g of groups){for(const a of [g.pva])records.push({source:'PV-A',category:g.category,generator_index:a.generator_index,generator_name:a.generator_name,seed:a.seed,asset_dir:a.asset_dir,urdf_path:a.urdf_path,appearance_path:a.appearance_path,physics_path:a.physics_path,package_path:a.package_path,texture_index:a.texture_index||[],renderer_script:'arti-template/scripts/render_exported_asset_blender.py',state_policy:'0=rest, 0.5=URDF joint-limit midpoint',texture_policy:'indexed_only'});records.push({source:'Articraft',category:g.category,asset_id:g.articraft.asset_id,asset_dir:g.articraft.asset_dir,urdf_path:g.articraft.urdf_path,package_path:g.articraft.package_path,texture_index:g.articraft.texture_index||[],renderer_script:'arti-template/scripts/render_exported_asset_blender.py',state_policy:'0=rest, 0.5=URDF joint-limit midpoint',texture_policy:'none'});records.push({source:'LAM',category:g.category,lam_category:g.lam.category,asset_id:g.lam.asset_id,asset_dir:g.lam.asset_dir,urdf_path:g.lam.urdf_path,package_path:g.lam.package_path,texture_index:g.lam.texture_index||[],renderer_script:'exp/scripts/render_articulated_object_code_asset_blender.py',state_policy:'0=rest, 0.5=URDF joint-limit midpoint',texture_policy:'packaged',render_mode:g.lam.render_mode,tier:g.lam.tier});}return {schema_version:2,generated_at:new Date().toISOString(),companion_asset_package:'articraft_lam_category_comparison_assets.zip',package_root:'source_assets',texture_policy:'PV-A textures are indexed only; Articraft has no detected textures; LAM source material textures are packaged.',asset_count:records.length,assets:records};}
function csvEscape(v){const s=String(v??'');return /[",\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}function indexCsv(index){const fields=['source','category','generator_index','generator_name','seed','lam_category','asset_id','asset_dir','urdf_path','package_path','renderer_script','state_policy','texture_policy','texture_index'];return [fields.join(','),...index.assets.map(x=>fields.map(f=>csvEscape(f==='texture_index'?JSON.stringify(x.texture_index||[]):x[f])).join(','))].join('\n')+'\n';}
function u16(v){return new Uint8Array([v&255,(v>>>8)&255]);}function u32(v){return new Uint8Array([v&255,(v>>>8)&255,(v>>>16)&255,(v>>>24)&255]);}function joinBytes(parts){const out=new Uint8Array(parts.reduce((n,x)=>n+x.length,0));let at=0;for(const part of parts){out.set(part,at);at+=part.length;}return out;}
function crc32(bytes){let c=0xffffffff;for(const byte of bytes){c^=byte;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;}
function makeZip(entries){const locals=[],centrals=[];let offset=0;for(const entry of entries){const name=new TextEncoder().encode(entry.name),data=entry.data,crc=crc32(data);const local=joinBytes([u32(0x04034b50),u16(20),u16(0x800),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);locals.push(local);const central=joinBytes([u32(0x02014b50),u16(20),u16(20),u16(0x800),u16(0),u16(0),u16(0),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]);centrals.push(central);offset+=local.length;}const centralBytes=joinBytes(centrals),localBytes=joinBytes(locals),end=joinBytes([u32(0x06054b50),u16(0),u16(0),u16(entries.length),u16(entries.length),u32(centralBytes.length),u32(localBytes.length),u16(0)]);return new Blob([localBytes,centralBytes,end],{type:'application/zip'});}
function dataUrlBytes(id){const raw=atob(IMAGES[id].split(',')[1]);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes;}
function downloadSelected(){const groups=chosenGroups();if(!groups.length){alert('请先勾选至少一个类别');return;}const selection={schema_version:1,generated_at:new Date().toISOString(),groups};const index=assetIndex(groups);const readme='This archive intentionally contains no rendered PNG files. The standalone HTML keeps all comparison images embedded.\nThe companion articraft_lam_category_comparison_assets.zip contains the renderable source files under source_assets/; use package_path in asset_index.json to locate them.\nPV-A textures are indexed only, Articraft has no detected textures, and LAM source material textures are included in the companion asset package.\n';const entries=[{name:'selection.json',data:new TextEncoder().encode(JSON.stringify(selection,null,2))},{name:'asset_index.json',data:new TextEncoder().encode(JSON.stringify(index,null,2))},{name:'asset_index.csv',data:new TextEncoder().encode(indexCsv(index))},{name:'README.txt',data:new TextEncoder().encode(readme)}];downloadBlob(makeZip(entries),'articraft_lam_selected_asset_index.zip');}
function openImage(b){$('lightbox-title').textContent=b.dataset.title;$('lightbox-image').src=IMAGES[b.dataset.image];$('lightbox').showModal();}
function importSelection(file){const reader=new FileReader();reader.onload=()=>{try{const x=JSON.parse(reader.result),groups=Array.isArray(x.groups)?x.groups:[];state.selected=new Set(groups.map(g=>g.category));for(const g of groups){if(g.pva?.seed)state.pva[g.category]=g.pva.seed;if(g.articraft?.asset_id)state.art[g.category]=g.articraft.asset_id;if(g.lam?.asset_id)state.lam[g.category]=g.lam.asset_id;}saveState();updateSummary();render();}catch(_){alert('JSON 文件格式无法读取');}};reader.readAsText(file);}
 $('search').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();render();});$('level').addEventListener('change',e=>{state.level=e.target.value;render();});$('only-selected').addEventListener('change',e=>{state.onlySelected=e.target.checked;render();});$('select-visible').addEventListener('click',()=>{visibleGroups().forEach(g=>state.selected.add(g.category));saveState();render();});$('clear-all').addEventListener('click',()=>{state.selected.clear();saveState();render();});$('export').addEventListener('click',exportSelection);$('download').addEventListener('click',downloadSelected);$('import').addEventListener('click',()=>$('import-file').click());$('import-file').addEventListener('change',e=>{if(e.target.files[0])importSelection(e.target.files[0]);});$('lightbox-close').addEventListener('click',()=>$('lightbox').close());$('lightbox').addEventListener('click',e=>{if(e.target===$('lightbox'))$('lightbox').close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('lightbox').open)$('lightbox').close();});loadState();updateSummary();render();
</script></body></html>'''


def main() -> int:
    payload, images = build_data(RENDER_ROOT)
    html = TEMPLATE.replace("__VIEWER_DATA__", json.dumps(payload, ensure_ascii=False, separators=(",", ":"))).replace("__IMAGE_DATA__", json.dumps(images, ensure_ascii=True, separators=(",", ":")))
    OUTPUT.write_text(html, encoding="utf-8")
    print(json.dumps({"output": str(OUTPUT), **payload["stats"]}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
